/* Strict replay of actual PendingHealTag and owning entry/heal phases. */
#define main gas_replay_main
#include "gas-lifecycle-test.c"
#undef main
static void capture_small(const pr_pokemon *p,double *v){v[0]=p->hp;v[1]=pr_get_stat(p,STAT_HP,true);v[2]=p->status;v[3]=p->status?p->status_toxic_turns:0;v[4]=p->status?p->status_sleep_turns:-1;v[5]=p->status?p->status_freeze_turns:-1;for(int k=0;k<2;k++)v[6+k]=PR_PP_USED(p)[k];}
static bool small_equal(const pr_pokemon *p,double *want){double got[8];capture_small(p,got);return !memcmp(got,want,sizeof got);}
static void tohex(const char *s,char *out,size_t cap){size_t n=strlen(s);if(2*n+1>cap)bad();for(size_t k=0;k<n;k++)snprintf(out+2*k,3,"%02x",(unsigned char)s[k]);}
static void pending_dump(pr_battle *bt,char *out,size_t cap){
 const pr_arena_tag *t=pr_arena_get_tag_on_side(bt,ARENA_TAG_TYPE_PENDING_HEAL,ARENA_TAG_SIDE_BOTH);out[0]=0;pr_text_source src={locale_get,NULL,"en"};
 if(t)for(int b=0;b<4;b++)for(int k=0;k<t->n_pending_heals;k++){const pr_pending_heal *h=&t->pending_heals[k];if(h->target_index!=b)continue;const char *key=h->move_id==MOVE_ID_LUNAR_DANCE?"moveTriggers:lunarDanceRestore":"moveTriggers:sacrificialFullRestore";pr_msg_arg a={"pokemonName",PR_ARG_POKEMON,h->pokemon_name,NULL,h->fusion_name};pr_msg m=pr_msg1(key,a);char text[1024],hex[2048];pr_msg_format(&m,&src,text,sizeof text);tohex(text,hex,sizeof hex);size_t at=strlen(out);int n=snprintf(out+at,cap-at,"%s%d,%lld,%d,%d,%s",at?";":"",b,(long long)h->source_id,h->move_id,h->restore_pp,hex);if(n<0||(size_t)n>=cap-at)bad();}
 if(!out[0])snprintf(out,cap,"-");
}
static bool check_dump(pr_battle *bt,const char *prefix){char actual[8192];pending_dump(bt,actual,sizeof actual);char *expected=line_read(prefix);expected[strcspn(expected,"\n")]=0;return !strcmp(actual,expected);}
int main(int argc,char **argv){
 if(argc!=2)return 2;input=fopen(argv[1],"r");if(!input||!getenv("TURNTEST_LOCALES"))return 2;pr_closures_init();double h[4];read_vector("PENDING ",h,4);if(h[0]!=2&&h[0]!=3&&h[0]!=4)bad();bool fused=h[0]==3,hp_context=h[0]==4;int n=integer(h[1],1024,100000),actors=integer(h[3],2,4),fail=0;if(actors!=2&&actors!=4)bad();
 for(int i=0;i<n;i++){
  static pr_battle bt;static pr_engine e;memset(&bt,0,sizeof bt);memset(&e,0,sizeof e);bt.engine=&e;e.n_levels=1;e.current=-1;bt.game_mode=GAME_MODES_CLASSIC;bt.ignoring_effect_source=-1;
  double c[5];read_vector("C ",c,5);if(c[0]!=i)bad();int b=integer(c[1],0,3),mode=integer(c[2],0,3),block=integer(c[3],0,1),nh=integer(c[4],0,3);if(b!=(actors==4?i%4:(i%2?2:0)))bad();bt.double_battle=actors==4;char *wave=line_read("W "),seed[128],extra;int turn;if(sscanf(wave,"%127s %d %c",seed,&turn,&extra)!=2||strlen(seed)>64||turn<1)bad();pr_seed_from_ascii(&bt.wave_seed,seed);bt.turn=turn;rng_read("R ",&bt.rng);rng_read("B ",&bt.battle_rng);bt.rng_live=bt.battle_rng_live=true;
  double v[8];read_vector("I ",v,8);double hp_override=0;if(hp_context){double x[1];read_vector("X ",x,1);double choices[]={0,1,2*v[1]+1,34359738371.};if(n!=8192||x[0]!=choices[(i/(256*actors))%4])bad();hp_override=x[0];}pr_pokemon mons[4]={0};
  for(int k=0;k<actors;k++){double sp[7];read_vector("S ",sp,fused?7:5);int slot=integer(sp[0],0,3);if(slot!=(actors==4?k:k*2))bad();pr_pokemon *p=&mons[k];p->id=integer(sp[1],1,1000);p->species=integer(sp[2],1,65535);p->form=integer(sp[3],0,255);if(fused){p->fusion_species=integer(sp[5],0,65535);p->fusion_form=integer(sp[6],0,255);}p->hp=p->stats[STAT_HP]=integer(sp[4],1,100000);p->is_player=slot<2;p->on_field=true;p->ability=p->base_ability=ABILITY_ID_BALL_FETCH;p->ability_override=-1;p->fusion_ability_index=-1;p->n_moves=2;p->moves[0]=MOVE_ID_TACKLE;p->moves[1]=MOVE_ID_SPLASH;for(int j=0;j<2;j++)p->max_pp_override[j]=-1;bt.field[slot]=bt.party[slot/2][slot%2]=p;bt.n_party[slot/2]++;}
  pr_pokemon *p=bt.field[b],*source=bt.field[b^2];p->summon_stats[STAT_HP]=hp_override;p->hp=integer(v[0],0,100000);p->stats[STAT_HP]=integer(v[1],1,100000);p->status=integer(v[2],0,STATUS_EFFECT_FAINT);p->status_toxic_turns=integer(v[3],0,100);p->status_sleep_turns=integer(v[4],-1,100);p->status_freeze_turns=integer(v[5],-1,100);for(int k=0;k<2;k++)p->pp_used[k]=integer(v[6+k],0,100);if(block)pr_add_tag(&bt,&e,p,BATTLER_TAG_TYPE_HEAL_BLOCK,3,MOVE_ID_HEAL_BLOCK,source->id);memset(&e,0,sizeof e);e.n_levels=1;e.current=-1;
  pr_arena_add_tag(&bt,&e,ARENA_TAG_TYPE_PENDING_HEAL,0,0,-1,ARENA_TAG_SIDE_BOTH,false);
  for(int k=0;k<nh;k++){char *row=line_read("H "),hex[2048],extra;int target,move,restore;long long sid;if(sscanf(row,"%d %lld %d %d %2047s %c",&target,&sid,&move,&restore,hex,&extra)!=5||target<0||target>3||(move!=MOVE_ID_HEALING_WISH&&move!=MOVE_ID_LUNAR_DANCE)||restore<0||restore>1)bad();pr_msg m=pr_msg1(move==MOVE_ID_LUNAR_DANCE?"moveTriggers:lunarDanceRestore":"moveTriggers:sacrificialFullRestore",pr_arg_pokemon(&bt,"pokemonName",source));pr_text_source textsrc={locale_get,NULL,"en"};char rendered[1024],expected[2048];pr_msg_format(&m,&textsrc,rendered,sizeof rendered);tohex(rendered,expected,sizeof expected);if(strcmp(expected,hex))bad();pr_arena_queue_heal_name(&bt,&e,target,sid,move,restore,pr_arg_pokemon(&bt,"",source));}
  bool ok=check_dump(&bt,"SI ");if(fused){double changed[4];read_vector("N ",changed,4);source->species=integer(changed[0],1,65535);source->form=integer(changed[1],0,255);source->fusion_species=integer(changed[2],0,65535);source->fusion_form=integer(changed[3],0,255);}int result=-1;if(mode==2){const pr_arena_tag *t=pr_arena_get_tag_on_side(&bt,ARENA_TAG_TYPE_PENDING_HEAL,ARENA_TAG_SIDE_BOTH);result=t&&t->n_pending_heals>0;pr_arena_lapse_tags(&bt,&e);}else if(mode==3){int ph=pr_phase_new(&e,PH_POST_SUMMON,b);pr_post_summon_phase(&bt,&e,ph);}else result=pr_arena_apply_pending_heal(&bt,&e,p,mode==1);
  double a[9];read_vector("A ",a,9);ok&=a[0]==result&&small_equal(p,a+1);ok&=check_dump(&bt,"SA ");double present[1];read_vector("L ",present,1);ok&=integer(present[0],0,1)==!!pr_arena_get_tag_on_side(&bt,ARENA_TAG_TYPE_PENDING_HEAL,ARENA_TAG_SIDE_BOTH);double q[1];read_vector("Q ",q,1);int nq=integer(q[0],0,16),seen=0,held[16];for(int l=0;l<e.n_levels;l++)for(int k=0;k<e.level_len[l];k++){int ph=e.levels[l][k];if(e.pool[ph].type!=PH_POKEMON_HEAL||seen>=16)bad();held[seen++]=ph;}
  ok&=seen==nq;for(int k=0;k<nq;k++){char *row=line_read("P "),hex[2048],extra;int target,full,skip,status,pp;double hp;if(sscanf(row,"%d %lf %d %d %d %d %2047s %c",&target,&hp,&full,&skip,&status,&pp,hex,&extra)!=7||target<0||target>3||!isfinite(hp)||hp<=0||floor(hp)!=hp||full<0||full>1||skip<0||skip>1||status<0||status>1||pp<0||pp>1)bad();if(k>=seen){ok=false;continue;}pr_phase *ph=&e.pool[held[k]];char rendered[1024],actual[2048];pr_text_source src={locale_get,NULL,"en"};pr_msg_format(&ph->msg,&src,rendered,sizeof rendered);tohex(rendered,actual,sizeof actual);ok&=target==ph->battler&&hp==ph->heal_hp&&!full&&skip&&status&&pp==!!(ph->heal_flags&PR_HEAL_RESTORE_PP)&&!strcmp(hex,actual);e.current=held[k];pr_phase_run(&bt,&e,held[k]);}
  for(int l=0;l<e.n_levels;l++)for(int k=0;k<e.level_len[l];k++){int ph=e.levels[l][k];if(e.pool[ph].type==PH_RESET_STATUS){e.current=ph;pr_phase_run(&bt,&e,ph);}}
  read_vector("O ",v,8);if(!small_equal(p,v)&&i<100){double got[8];capture_small(p,got);fprintf(stderr,"small%d ",i);for(int z=0;z<8;z++)fprintf(stderr,"%g/%g ",got[z],v[z]);fprintf(stderr,"\n");}ok&=small_equal(p,v);ok&=check_dump(&bt,"SO ");char text[8192]="",hex[16384];pr_text_source src={locale_get,NULL,"en"};for(int l=0;l<e.n_levels;l++)for(int k=0;k<e.level_len[l];k++){pr_phase *ph=&e.pool[e.levels[l][k]];if(ph->type!=PH_MESSAGE)continue;char rendered[1024];pr_msg_format(&ph->msg,&src,rendered,sizeof rendered);if(text[0])strcat(text,"\n");if(strlen(text)+strlen(rendered)>=sizeof text)bad();strcat(text,rendered);}if(text[0])tohex(text,hex,sizeof hex);else strcpy(hex,"-");char *want=line_read("T ");want[strcspn(want,"\n")]=0;if(strcmp(want,hex)&&i<100)fprintf(stderr,"text%d C%s JS%s\n",i,hex,want);ok&=!strcmp(want,hex);pr_rng r;rng_read("RO ",&r);ok&=rng_equal(r,bt.rng);rng_read("BO ",&r);ok&=rng_equal(r,bt.battle_rng);if(strcmp(line_read("E"),"\n"))bad();ok&=!bt.n_unported&&!e.overflow;if(!ok){if(fail<16)fprintf(stderr,"pending case%d mode%d hp%d status%d queue%d/%d\n",i,mode,p->hp,p->status,seen,nq);if(fail<16)fprintf(stderr,"unported %d %s\n",bt.n_unported,bt.n_unported?pr_unported_name(bt.unported[0]):"none");fail++;}
 }
 double end[1];read_vector("PENDING_COMPLETE ",end,1);if(end[0]!=n||fgetc(input)!=EOF)bad();printf("Pending heal: %d complete, %d exact, %d failures\n",n,n-fail,fail);return fail?1:0;
}
